window.docContents[36].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Synthesis":{"contents":"This example uses the grammar! syntax extension for grammars, but they can also be built using\nthe Grammar API.\n\n#eval Env.runIO do\n  let s ← Solver.new\n  s.setOption \"sygus\" \"true\"\n\n  let g ← grammar! s (x y : Int) where\n    start : Int  := x | y | if cnd then start else start\n    cnd   : Bool := start ≤ start\n\n  let mx ← s.synthFun \"max\" g\n  let a ← s.declareSygusVar Int \"a\"\n  let b ← s.declareSygusVar Int \"b\"\n  let mab ← smt! mx a b\n  s.addSygusConstraint (← smt! mab ≥ a)\n  s.addSygusConstraint (← smt! mab ≥ b)\n  s.addSygusConstraint (← smt! mab = a ∨ mab = b)\n\n  s.checkSynth (ifSolved := do\n    println! \"max := {(← s.getSynthSolution mx).erase}\")\n\n\nmax := (lambda ((x Int) (y Int)) (ite (<= y x) x y))\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.4. Synthesis","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Synthesis"}});